Object accountId = store.values().get("accountId");
data.close();
Assert.assertTrue(api.records.isEmpty());
Assert.assertEquals(api.deletes.subList(0, 2), List.of(store.id(), store.id()));
Assert.assertEquals(api.deletes.get(2), accountId);

Api api = new Api(); api.timeOutStore = true; api.commitBeforeTimeout = true;
DealerTestData data = new DealerTestData(api.driver());
DealerTestData.Record store = data.store();
data.close();
Assert.assertTrue(api.records.isEmpty());
Assert.assertEquals(api.deletes.stream().filter(store.id()::equals).count(), 1L);

Api api = new Api(); api.timeOutStore = true; api.commitBeforeTimeout = true;
api.emptyDeletedResponse = true;
DealerTestData data = new DealerTestData(api.driver());
DealerTestData.Record store = data.store();
data.close();
Assert.assertTrue(api.records.isEmpty());
Assert.assertEquals(api.deletes.stream().filter(store.id()::equals).count(), 1L);

Api api = new Api(); api.rejectStore = true;
api.records.put("shared-record", new LinkedHashMap<>(Map.of("arabicName", "Existing business data")));
DealerTestData data = new DealerTestData(api.driver());
DealerTestData.Record store = data.store();
Assert.expectThrows(AssertionError.class, data::close);
Assert.assertEquals(api.deletes, List.of(store.id()));
Assert.assertEquals(api.records.size(), 4);
api.rejectStore = false;
data.close();
Assert.assertEquals(api.records.keySet(), java.util.Set.of("shared-record"));

Api api=new Api();var data=new DealerTestData(api.driver());data.beginScenario();var stable=data.area();var first=data.item(1);var account=data.account();
data.beginScenario();var second=data.item(1);Assert.assertNotEquals(first.id(),second.id());Assert.assertNotEquals(first.values().get("mainUnitBarcode"),second.values().get("mainUnitBarcode"));Assert.assertNotEquals(account.id(),data.account().id());Assert.assertEquals(data.area().id(),stable.id());
Assert.assertTrue(api.records.containsKey(first.id()));Assert.assertTrue(api.deletes.isEmpty());data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();var data=new DealerTestData(api.driver());var first=data.area();var last=data.unit();api.crashAtDelete=2;
Assert.expectThrows(Error.class,data::close);String suffix=last.name().substring(last.name().length()-12);
var rows=new org.json.JSONArray(java.nio.file.Files.readString(java.nio.file.Path.of("target","dealer-fixtures",suffix+".json")));
Assert.assertTrue(rows.toList().stream().noneMatch(v->last.id().equals(((Map<?,?>)v).get("id"))));
api.crashAtDelete=0;DealerTestData.resume(api.driver(),suffix).close();Assert.assertTrue(api.records.isEmpty());Assert.assertEquals(java.util.Collections.frequency(api.deletes,last.id()),1);

