  harness.beginDealerCase();Assert.assertSame(harness.data(),data);var second=data.account();String two=harness.ownedName(page,Plugin_ERP.Enums.Pages.CUSTOMERS,"SECOND");api.records.put("Customers-owned-2",new LinkedHashMap<>(Map.of("id","Customers-owned-2","arabicName",two,"accountId",second.id())));browser.addAuxiliaryWindow();harness.cleanScenarioRecords();
  Assert.assertTrue(api.records.containsKey(first.id()));Assert.assertTrue(api.records.containsKey(second.id()));Assert.assertTrue(api.deletes.isEmpty());Assert.assertEquals(browser.closed,2);
  api.rejectDealer=true;Assert.expectThrows(AssertionError.class,harness::retryRemainingScenarioCleanup);Assert.assertTrue(api.deletes.stream().noneMatch(id->id.startsWith("Accounts-")));Assert.assertTrue(api.records.containsKey(first.id()));
  api.rejectDealer=false;harness.retryRemainingScenarioCleanup();Assert.assertTrue(api.records.isEmpty());Assert.assertTrue(api.deletes.indexOf(first.id())>api.deletes.indexOf("Customers-owned-1"));
}

