methods.body:
Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);
var movement=data.fixture("movement","ItemTransactions-ExchangeOrder",StoreTestData.fields("storeId",store.id(),"lines",List.of(Map.of("itemId",item.id()))));
api.records.put("existing-movement",new LinkedHashMap<>(Map.of("id","existing-movement","notes","Business record")));
data.close();Assert.assertTrue(api.deletes.indexOf(movement.id())<api.deletes.indexOf(item.id()));
Assert.assertTrue(api.deletes.indexOf(item.id())<api.deletes.indexOf(store.id()));Assert.assertEquals(api.records.keySet(),java.util.Set.of("existing-movement"));

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);
data.fixture("movement","ItemTransactions-ExchangeOrder",StoreTestData.fields("storeId",store.id(),"lines",List.of(Map.of("itemId",item.id()))));
api.rejectMovement=true;Assert.expectThrows(AssertionError.class,data::close);
Assert.assertTrue(api.records.containsKey(item.id()));Assert.assertTrue(api.records.containsKey(store.id()));
api.rejectMovement=false;data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var unit=data.unit(1);
api.records.put(unit.id().toString(),new LinkedHashMap<>(Map.of("id",unit.id(),"arabicName","Different business record")));
Assert.expectThrows(AssertionError.class,data::close);Assert.assertTrue(api.deletes.isEmpty());
api.records.put(unit.id().toString(),new LinkedHashMap<>(Map.of("id",unit.id(),"arabicName",unit.name())));data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);
Map<String,Object> values=StoreTestData.fields("id","owned-manufacturing","notes","","storeId",store.id(),"lines",List.of(Map.of("itemId",item.id(),"unitId",data.unit(1).id())));
api.records.put("owned-manufacturing",new LinkedHashMap<>(values));data.track("ManufacturingOrders","owned-manufacturing","QA-ST-manufacturing",values);
data.close();Assert.assertEquals(api.deletes.get(0),"owned-manufacturing");Assert.assertTrue(api.records.isEmpty());

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);String marker="QA-ST-lost-create";
Map<String,Object> values=StoreTestData.fields("notes",marker,"storeId",store.id(),"transactionType","ExchangeOrder","lines",List.of(Map.of("itemId",item.id(),"unitId",data.unit(1).id())));
Map<String,Object> stored=new LinkedHashMap<>(values);stored.put("id","lost-create");api.records.put("lost-create",stored);
data.rememberAttempts(List.of(StoreTestData.fields("endpoint","ItemTransactions-ExchangeOrder","values",values)),List.of(),marker);
data.close();Assert.assertEquals(api.deletes.get(0),"lost-create");Assert.assertTrue(api.records.isEmpty());

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);
Map<String,Object> values=StoreTestData.fields("notes","QA-ST-unresolved","storeId",store.id(),"lines",List.of(Map.of("itemId",item.id(),"unitId",data.unit(1).id())));
data.rememberAttempts(List.of(StoreTestData.fields("endpoint","ItemTransactions-ExchangeOrder","values",values)),List.of(),"QA-ST-unresolved");
api.failMovementLookup=true;Assert.expectThrows(AssertionError.class,data::close);Assert.assertTrue(api.deletes.isEmpty());Assert.assertTrue(api.records.containsKey(item.id()));
api.failMovementLookup=false;data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();StoreTestData data=new StoreTestData(api.driver());var item=data.item(1);var store=data.store(1);String marker="QA-ST-lost-update";
Map<String,Object> original=StoreTestData.fields("id","lost-update","notes",marker,"storeId",store.id(),"lines",List.of(Map.of("itemId",item.id(),"unitId",data.unit(1).id())));
api.records.put("lost-update",new LinkedHashMap<>(original));data.track("ItemTransactions-ExchangeOrder","lost-update",marker,original);
Map<String,Object> updated=new LinkedHashMap<>(original);updated.put("notes",marker+" EDIT");api.records.put("lost-update",updated);
data.rememberAttempts(List.of(StoreTestData.fields("endpoint","ItemTransactions-ExchangeOrder","values",updated)),List.of(),marker);
data.close();Assert.assertEquals(api.deletes.get(0),"lost-update");Assert.assertTrue(api.records.isEmpty());

Api api=new Api();api.missingDelete400=true;
StoreTestData data=new StoreTestData(api.driver());
