data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();ProductsTestData data=new ProductsTestData(api.driver());
ProductsTestData.Record unit=data.unit(1);api.missingDeleteForExisting=true;
Assert.expectThrows(AssertionError.class,data::close);Assert.assertTrue(api.records.containsKey(unit.id()));
api.missingDeleteForExisting=false;data.close();Assert.assertTrue(api.records.isEmpty());

Api api=new Api();ProductsTestData data=new ProductsTestData(api.driver());
ProductsTestData.Record unit=data.unit(1),category=data.category();
String name="QA-PR-recover-"+java.util.UUID.randomUUID();
Map<String,Object> values=ProductsTestData.fields("arabicName",name,"mainUnitId",unit.id(),"categoryId",category.id());
Map<String,Object> saved=new LinkedHashMap<>(values);saved.put("id","Items-ui");api.records.put("Items-ui",saved);
